package net.battlespades.bot;
import java.util.*;
import net.battlespades.physics.PlayerPhysics.Vector;
import static net.battlespades.bot.BotMessages.*;
import static net.battlespades.bot.BotState.*;
import static net.battlespades.bot.BotVectors.*;

/** Exclusive goal selection, stable per-life flank approaches and bounded optional formation commitments. */
final class BrainGoals {
    private BrainGoals(){}
    static final Set<String> ASSAULT=Set.of("team_assault_enemy_side","arena_elimination_push","vip_mop_up");
    static BotGoal from(BotModeDecision d){return new BotGoal(List.of("objective",d.role()),d.position(),d.role(),Math.max(.75,d.arrivalRadius()),d.sprint(),d.watchPosition());}
    static BotGoal select(BotNavigationWorld world,BotModePolicies.Memory memory,Perception f,Player p,BotBrainState state,double now,BotModeDecision decision){if(decision==null)decision=memory.decide(f,p);if(decision!=null&&(BotModePolicies.committed(decision)||decision.objectivePriority()>=.7)){if(ASSAULT.contains(decision.role())){var flank=flank(world,f,p,state,now);return flank!=null?flank:assault(world,p,state,decision,now);}if(Set.of("ctf_attack_intel","classic_ctf_attack_intel").contains(decision.role())){var flank=flank(world,f,p,state,now);if(flank!=null)return flank;}return from(decision);}if(state.contactPosition!=null&&now<state.contactUntil)return new BotGoal(List.of("contact",state.contactId,state.contactGeneration),state.contactPosition,"chase_last_seen",1.75,true,null);if(decision==null)return null;decision=optionalSupport(f,p,state,decision,now);if(ASSAULT.contains(decision.role())){var flank=flank(world,f,p,state,now);return flank!=null?flank:assault(world,p,state,decision,now);}return from(decision);}
    static BotGoal flank(BotNavigationWorld w,Perception f,Player p,BotBrainState state,double now){if(state.flankDecided&&state.flankPoint==null)return null;var own=BotModePolicies.objective(f,"team_anchor",p.team());var enemy=BotModePolicies.enemy(f,"team_anchor",p);if(own==null||enemy==null)return null;double ax=enemy.position().x()-own.position().x(),ay=enemy.position().y()-own.position().y(),length=Math.hypot(ax,ay);if(length<140){state.flankDecided=true;return null;}double ux=ax/length,uy=ay/length,along=((p.position().x()-own.position().x())*ux+(p.position().y()-own.position().y())*uy)/length;if(!state.flankDecided){state.flankDecided=true;var profile=f.profile()==null?BrainInventory.fallback(p.id()):f.profile();double appetite=.3+.35*profile.creativity()+.2*profile.caution()-.25*profile.aggression();if(along>.3||BotCombatTactics.mix(p.id(),p.lifeId(),41)>appetite)return null;double side=BotCombatTactics.mix(p.id(),p.lifeId(),43)<.5?1:-1;for(int attempt=0;attempt<3;attempt++){double lateral=side*(34+46*BotCombatTactics.mix(p.id(),p.lifeId(),47+attempt)),stage=.42+.16*BotCombatTactics.mix(p.id(),p.lifeId(),53+attempt),x=own.position().x()+ax*stage-uy*lateral,y=own.position().y()+ay*stage+ux*lateral;if(x<16||x>495||y<16||y>495){side=-side;continue;}var surface=w.surface((int)x,(int)y,p.position().z(),48,false);if(surface!=null){state.flankPoint=surface.position();state.flankUntil=now+75;break;}side=-side;}}var point=state.flankPoint;if(point==null)return null;if(!state.flankStarted&&along<.1){state.flankUntil=now+75;return null;}state.flankStarted=true;if(along>=.55||now>=state.flankUntil||state.contactPosition!=null&&now<state.contactUntil||flat(point,p.position())<=10){state.flankPoint=null;return null;}return new BotGoal(List.of("flank",p.lifeId()),point,"tdm_flank_approach",10,true,null);}
    static BotModeDecision optionalSupport(Perception f,Player p,BotBrainState state,BotModeDecision d,double now){if(!d.role().equals("tdm_squad_support"))return d;if(!p.wade()&&flat(p.position(),d.position())<=d.arrivalRadius()&&Math.abs(p.position().z()-d.position().z())<=3){state.corridorFailedGoal=null;state.supportRetryAt=0;state.supportRejectedGoal=null;state.supportProgressAnchor=null;state.supportNoProgressTime=0;state.supportLastDecisionAt=null;state.supportFailedGoal=null;state.supportEscapeAttempted=false;return d;}if(state.supportRejectedGoal!=null&&distance(d.position(),state.supportRejectedGoal)>=8){state.supportRetryAt=0;state.supportRejectedGoal=null;}if(now>=state.supportRetryAt){var anchor=state.supportProgressAnchor;if(anchor==null||distance(anchor,d.position())>=16){state.supportProgressAnchor=anchor=d.position();state.supportBestDistance=distance(p.position(),anchor);state.supportNoProgressTime=0;state.supportFailedGoal=null;state.supportEscapeAttempted=false;}double gap=distance(p.position(),anchor);if(gap+4<=state.supportBestDistance){state.supportBestDistance=gap;state.supportNoProgressTime=0;state.supportFailedGoal=null;state.supportEscapeAttempted=false;}else if(state.supportLastDecisionAt!=null){double elapsed=now-state.supportLastDecisionAt;var step=state.routeIndex<state.route.size()?state.route.get(state.routeIndex):null;if(elapsed>=0&&elapsed<=1&&(step==null||step.affordance()!=Affordance.BREACH))state.supportNoProgressTime+=elapsed;}}state.supportLastDecisionAt=now;boolean failed=state.supportNoProgressTime>=15&&state.supportEscapeAttempted&&state.supportFailedGoal!=null&&now-state.supportFailureAt<=30&&distance(d.position(),state.supportFailedGoal)<=3;if(!failed&&now>=state.supportRetryAt)return d;var enemy=BotModePolicies.enemy(f,"team_anchor",p);if(enemy==null)return d;if(failed&&now>=state.supportRetryAt){state.supportRejectedGoal=d.position();state.supportRetryAt=now+30;state.supportProgressAnchor=null;state.supportNoProgressTime=0;state.supportFailedGoal=null;state.supportEscapeAttempted=false;}return BotModePolicies.d(enemy.position(),"team_assault_enemy_side",true,5,BotModeDecision.Posture.ASSAULT,.6,160);}
    static BotGoal assault(BotNavigationWorld w,Player p,BotBrainState state,BotModeDecision d,double now){var position=state.patrolPosition==null?d.position():state.patrolPosition;boolean arrived=flat(position,p.position())<=d.arrivalRadius()&&Math.abs(position.z()-p.position().z())<=3;if(!arrived)state.patrolArrivedAt=null;else if(state.patrolArrivedAt==null)state.patrolArrivedAt=now;boolean finished=state.patrolArrivedAt!=null&&now-state.patrolArrivedAt>=3,expired=state.patrolPosition!=null&&now-state.patrolStartedAt>=45;if(finished||expired){state.patrolIndex++;state.patrolStartedAt=now;state.patrolArrivedAt=null;for(int offset=0;offset<8;offset++){double angle=(state.patrolIndex+p.id()*3+offset)*Math.PI/4,radius=20+Math.floorMod(p.id(),3)*6;int x=Math.clamp((int)(d.position().x()+Math.cos(angle)*radius),1,510),y=Math.clamp((int)(d.position().y()+Math.sin(angle)*radius),1,510);var surface=w.surface(x,y,d.position().z(),12,3,false);if(surface!=null){state.patrolPosition=surface.position();break;}}}return state.patrolPosition==null?from(d):new BotGoal(List.of("assault_search",state.patrolIndex),state.patrolPosition,"team_assault_search",d.arrivalRadius(),true,null);}
}
